"use client";

import { useState } from "react";

export default function TimeLogForm({
  onSaved,
}: {
  onSaved: () => void;
}) {
  const [workDate, setWorkDate] = useState("");
  const [timeIn, setTimeIn] = useState("");
  const [timeOut, setTimeOut] = useState("");
  const [remarks, setRemarks] = useState("");
  const [saving, setSaving] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!workDate || !timeIn || !timeOut) {
      alert("Please enter the date, time in, and time out.");
      return;
    }

    setSaving(true);

    try {
      const response = await fetch("/api/timelogs", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          workDate,
          timeIn,
          timeOut,
          remarks,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        alert(data.error || "Failed to save time log.");
        return;
      }

      setWorkDate("");
      setTimeIn("");
      setTimeOut("");
      setRemarks("");

      onSaved();
    } catch (error) {
      console.error(error);
      alert("Something went wrong.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div>
        <label 
          htmlFor="workDate"
          className="mb-2 block text-sm font-medium text-gray-700"
        >
          Date
        </label>

        <input
          id="workDate"
          type="date"
          value={workDate}
          onChange={(e) => setWorkDate(e.target.value)}
          className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          required
          disabled={saving}
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label
            htmlFor="timeIn"
            className="mb-2 block text-sm font-medium text-gray-700"
          >
            Time In
          </label>

        <input
          id="timeIn"
          type="time"
          value={timeIn}
          onChange={(e) => setTimeIn(e.target.value)}
          className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          required
          disabled={saving}
        />
        </div>

        <div>
          <label
            htmlFor="timeOut"
            className="mb-2 block text-sm font-medium text-gray-700"
          >
            Time Out
          </label>

          <input
            id="timeOut"
            type="time"
            value={timeOut}
            onChange={(e) => setTimeOut(e.target.value)}
            className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-2 focus_ring-blue-200"
            required
            disabled={saving}
          />
        </div>
      </div>

      <div>
        <label
          htmlFor="remarks"
          className="mb-2 block text-sm font-medium text-gray-700"
        >
          Remarks
        </label>

        <textarea
          id="remarks"
          value={remarks}
          onChange={(e) => setRemarks(e.target.value)}
          rows={3}
          placeholder="Optional"
          className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          disabled={saving}
        />
      </div>

      <button 
        type="submit" 
        disabled={saving}
        className="w-full rounded-lg bg-blue-600 px-4 py-3 font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
      >
        {saving ? "Saving..." : "Save Time Log"}
      </button>
    </form>
  );
}